<template>
  <section class="billing-transactions" aria-labelledby="transaction-heading">
    <header><div><h2 id="transaction-heading">Billing transaction history</h2><p>Recorded payer payments, family payments, refunds, adjustments and patient responsibility.</p></div><button type="button" :disabled="loading" @click="load">Refresh transactions</button></header>
    <form class="transaction-search" @submit.prevent="applySearch"><label>Search transactions<input v-model="searchInput" placeholder="Patient, claim, payer or transaction" /></label><button :disabled="loading">Search</button></form>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="loading" role="status">Loading transaction history…</p><p v-else-if="!available">Transaction history is unavailable until billing setup is complete.</p>
    <p v-if="!loading && available && !familyPaymentsAvailable" role="status">Payer transactions are available. Family payment history is not available for this scope.</p>
    <div v-if="!loading && available" class="table-scroll"><table><thead><tr><th v-for="column in columns" :key="column.id" :aria-sort="sortBy === column.id ? direction === 'asc' ? 'ascending' : 'descending' : 'none'"><button type="button" @click="sort(column.id)">{{ column.label }} {{ sortBy === column.id ? direction === 'asc' ? '↑' : '↓' : '↕' }}</button></th></tr></thead><tbody><tr v-for="item in rows" :key="`${item.agency_id}:${item.id}`"><td>{{ timestamp(item.posted_at) }}</td><td>{{ organization(item)?.name || 'Organization' }}</td><td><a :href="clientLink(item)">{{ item.client_name || `Client #${item.client_id}` }}</a><button v-if="item.claimId" class="link" type="button" @click="emit('open-claim', {...item, id:item.claimId, claimId:item.claimId, key:`claim:${item.claimId}`, source:'claim', readOnly:true})">{{ item.claim_number || `Claim #${item.claimId}` }}</button></td><td>{{ billingDate(item.date_of_service) }}</td><td>{{ item.payer_name || 'Not recorded' }}</td><td>{{ kindLabel(item.kind) }}<small v-if="item.reverses_posting_id">Reverses transaction #{{ item.reverses_posting_id }}</small></td><td>{{ kindLabel(item.status) }}</td><td>{{ money(item.amount_cents) }}</td><td>{{ money(item.paid_cents) }}</td><td>{{ money(item.adjustment_cents) }}</td><td>{{ money(item.responsibility_cents) }}</td><td>{{ item.provider_name || 'Not recorded' }}</td></tr></tbody></table><p v-if="!rows.length" class="empty">No recorded transactions match this scope and search.</p></div>
    <nav class="pagination" aria-label="Transaction pages"><span>{{ total }} transactions · Page {{ page }} of {{ Math.max(1, Math.ceil(total / pageSize)) }}</span><div><button :disabled="loading || page <= 1" @click="page--">Previous</button><button :disabled="loading || page * pageSize >= total" @click="page++">Next</button></div></nav>
  </section>
</template>
<script setup>
import { ref, watch, onBeforeUnmount } from 'vue';
import api from '../../services/api';
import { billingDate } from '../../utils/billingWorkspace.js';
const props=defineProps({ agencyId:[String,Number], clientId:[String,Number] });
const emit=defineEmits(['open-claim']);
const rows=ref([]),organizations=ref([]),loading=ref(false),error=ref(''),available=ref(true),familyPaymentsAvailable=ref(true),total=ref(0),page=ref(1),pageSize=ref(30),searchInput=ref(''),search=ref(''),sortBy=ref('posted_at'),direction=ref('desc');
let sequence=0;
const columns=[['posted_at','Posted'],['organization','Organization'],['client_name','Patient / claim'],['date_of_service','Date of service'],['payer_name','Payer'],['kind','Transaction'],['status','Status'],['amount_cents','Transaction amount'],['paid_cents','Payment recorded'],['adjustment_cents','Adjustment'],['responsibility_cents','Patient responsibility'],['provider_name','Posted by']].map(([id,label])=>({id,label}));
const money=value=>value==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(value)/100);
const timestamp=value=>{if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?'—':d.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});};
const kindLabel=value=>({insurance_payment:'Insurance payment',adjudication:'Payer adjudication',reversal:'Reversal',adjustment:'Adjustment',succeeded:'Succeeded',pending:'Pending',failed:'Failed',refunded:'Refunded',posted:'Posted'}[value]||String(value||'Transaction').replaceAll('_',' '));
const organization=item=>organizations.value.find(org=>Number(org.id)===Number(item.agency_id));
const clientLink=item=>`${organization(item)?.slug?`/${encodeURIComponent(organization(item).slug)}`:''}/admin/clients/${Number(item.client_id)}?tab=billing&agencyId=${Number(item.agency_id)}`;
function applySearch(){search.value=searchInput.value.trim();page.value=1;}
function sort(id){direction.value=sortBy.value===id&&direction.value==='asc'?'desc':'asc';sortBy.value=id;page.value=1;}
async function load(){const current=++sequence;loading.value=true;error.value='';rows.value=[];try{const {data}=await api.get('/medical-billing/workspace/transactions',{params:{...(props.agencyId&&props.agencyId!=='all'?{agencyId:props.agencyId}:{}),...(props.clientId?{clientId:props.clientId}:{}),page:page.value,search:search.value,sortBy:sortBy.value,direction:direction.value},skipGlobalLoading:true});if(current!==sequence)return;rows.value=data.transactions||[];organizations.value=data.organizations||[];total.value=Number(data.total||0);pageSize.value=Number(data.pageSize||30);available.value=data.available!==false;familyPaymentsAvailable.value=data.familyPaymentsAvailable!==false;}catch(e){if(current===sequence){error.value=e.response?.data?.error?.message||'Transaction history could not be loaded.';rows.value=[];total.value=0;}}finally{if(current===sequence)loading.value=false;}}
watch(()=>[props.agencyId,props.clientId],()=>{page.value=1;rows.value=[];load();},{immediate:true});watch([page,search,sortBy,direction],load);onBeforeUnmount(()=>sequence++);
</script>
<style scoped>
.billing-transactions{padding:22px;border:1px solid var(--app-line,#dfe6ef);border-radius:12px;background:var(--app-surface,#fff);margin-top:20px}header,.transaction-search,.pagination{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}h2{margin:0;font-size:19px}p{color:var(--app-muted,#63718a);line-height:1.5}.transaction-search{justify-content:flex-start;margin:20px 0;align-items:end}.transaction-search label{display:grid;gap:6px;font-size:12px}.transaction-search input{min-width:300px;max-width:100%;padding:10px;border:1px solid #cbd8e5;border-radius:7px;font:inherit}button{cursor:pointer;padding:9px 12px;border:1px solid #cbd8e5;border-radius:7px;background:var(--app-surface,#fff);color:var(--app-text-blue,#1555b0);font:inherit}button:disabled{opacity:.5;cursor:default}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;text-align:left}th,td{padding:12px 10px;border-bottom:1px solid #e5ecf5;vertical-align:top;min-width:100px}th{background:#f4f7fb;font-size:11px;white-space:nowrap}th button,.link{padding:0;border:0;background:none;text-align:left}.link,small{display:block;margin-top:5px}a{color:#1555b0}.pagination{margin-top:18px;font-size:12px}.pagination>div{display:flex;gap:10px}[role=alert]{color:#a71925}@media(max-width:600px){.billing-transactions{padding:15px}.transaction-search input{min-width:0;width:100%}.transaction-search label{width:100%}}
</style>
